package com.nthexperience.desktop;

import android.app.Activity;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.net.Uri;
import android.text.*;
import android.text.style.*;
import android.view.Gravity;
import android.widget.*;
import java.io.*;
import java.nio.charset.StandardCharsets;

/** Rich text with a local draft and portable HTML export; it never overwrites a source file. */
final class EightWordPad extends LinearLayout {
    static final int OPEN=8504,SAVE=8505;final Activity activity;final DesktopStore store;final EditText editor;final TextView status;boolean restoring;
    EightWordPad(Activity a,DesktopStore store){super(a);activity=a;this.store=store;setOrientation(VERTICAL);setBackgroundColor(0xfff0f0f0);setContentDescription("Eight WordPad");TenAppearance.preserve(this);
        HorizontalScrollView scroll=new HorizontalScrollView(a);LinearLayout commands=new LinearLayout(a);for(String name:new String[]{"New","Open","Save as","Bold","Italic","Underline","Clear formatting","Text size","Share"}){TextView b=Aero.text(a,name,13,0xff154d78);b.setMinHeight(dp(48));b.setPadding(dp(12),dp(12),dp(12),dp(12));b.setContentDescription("WordPad "+name);b.setFocusable(true);b.setOnClickListener(v->command(name));commands.addView(b);}scroll.addView(commands);addView(scroll);
        editor=new EditText(a);editor.setGravity(Gravity.TOP|Gravity.START);editor.setTextColor(Color.BLACK);editor.setBackgroundColor(Color.WHITE);editor.setTextSize(18);editor.setPadding(dp(20),dp(18),dp(20),dp(18));editor.setContentDescription("WordPad document");editor.setHint("Write a document…");editor.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);editor.setFilters(new InputFilter[]{new InputFilter.LengthFilter(50000)});editor.setText(Html.fromHtml(store.prefs.getString("eight_wordpad_html",""),Html.FROM_HTML_MODE_LEGACY));addView(editor,new LayoutParams(-1,0,1));status=Aero.text(a,"Draft saved on this device · Save as exports HTML",12,0xff555555);status.setPadding(dp(10),dp(6),dp(10),dp(6));addView(status);editor.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){}public void afterTextChanged(Editable e){if(!restoring)saveDraft();}});}
    int dp(int n){return Aero.dp(getContext(),n);}
    String html(){return Html.toHtml(editor.getText(),Html.TO_HTML_PARAGRAPH_LINES_CONSECUTIVE);}
    void saveDraft(){store.prefs.edit().putString("eight_wordpad_html",html()).apply();}
    void command(String command){switch(command){case "New":Aero.dialog(activity).setTitle("Start a new document?").setMessage("Save as first if you want to keep the current draft.").setPositiveButton("New",(d,w)->editor.setText("")).setNegativeButton("Cancel",null).show();break;case "Open":pick(false);break;case "Save as":pick(true);break;case "Bold":style(new StyleSpan(Typeface.BOLD));break;case "Italic":style(new StyleSpan(Typeface.ITALIC));break;case "Underline":style(new UnderlineSpan());break;case "Clear formatting":int start=Math.max(0,Math.min(editor.getSelectionStart(),editor.getSelectionEnd())),end=Math.max(0,Math.max(editor.getSelectionStart(),editor.getSelectionEnd()));if(start<end)editor.getText().replace(start,end,editor.getText().subSequence(start,end).toString());saveDraft();break;case "Text size":Aero.dialog(activity).setTitle("Selected text size").setItems(new String[]{"12","16","20","24","32"},(d,n)->style(new AbsoluteSizeSpan(new int[]{12,16,20,24,32}[n],true))).show();break;case "Share":activity.startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,editor.getText().toString()),"Share document text"));break;}}
    void style(Object style){int start=Math.max(0,editor.getSelectionStart()),end=Math.max(0,editor.getSelectionEnd());if(start==end){status.setText("Select some text, then choose its formatting.");return;}editor.getText().setSpan(style,Math.min(start,end),Math.max(start,end),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);saveDraft();status.setText("Formatting applied · Draft saved");}
    void pick(boolean save){Intent intent=new Intent(save?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(save?"text/html":"text/*");if(save)intent.putExtra(Intent.EXTRA_TITLE,"Document.html");try{activity.startActivityForResult(intent,save?SAVE:OPEN);}catch(ActivityNotFoundException ex){status.setText("No document picker is available.");}}
    void result(int request,Intent data){Uri uri=data.getData();if(uri==null)return;String source=html();status.setText(request==SAVE?"Saving…":"Opening…");new Thread(()->{String error="",loaded=null;try{if(request==SAVE){try(OutputStream out=activity.getContentResolver().openOutputStream(uri,"wt")){out.write(source.getBytes(StandardCharsets.UTF_8));}}else{try(InputStream in=activity.getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1){if(out.size()+n>512*1024)throw new IOException("Document exceeds 512 KB");out.write(bytes,0,n);}String content=out.toString("UTF-8");String type=activity.getContentResolver().getType(uri);loaded=type!=null&&type.contains("html")?content:TextUtils.htmlEncode(content).replace("\n","<br>");}}}catch(Exception ex){error="Could not "+(request==SAVE?"save":"open")+" this document. Use a readable text/HTML file under 512 KB.";}String result=loaded,message=error;post(()->{if(!message.isEmpty()){status.setText(message);return;}if(result!=null)editor.setText(Html.fromHtml(result,Html.FROM_HTML_MODE_LEGACY));status.setText(request==SAVE?"HTML document exported":"Document opened · Changes are saved in your local draft");});},"Eight-WordPad-file").start();}
}
